mapper.select:
SELECT t.tender_id, t.tender_code, t.tender_name, t.tender_type, t.tender_mode, t.company_id AS purchaser_id, t.budget_amount, t.currency, t.tax_rate, t.is_tax_included, t.purchase_nature, t.open_time, t.open_address, t.publish_time, t.bid_end_time, t.status, t.project_id, t.created_by, t.created_time,
-- PM 信息 MAX(CASE WHEN tm.member_role = 'PM' THEN tm.person_id END) AS person_id, MAX(CASE WHEN tm.member_role = 'PM' THEN tm.member_role END) AS member_role, MAX(CASE WHEN tm.member_role = 'PM' THEN tm.org_id END) AS org_id, MAX(CASE WHEN tm.member_role = 'PM' THEN tm.post_id END) AS post_id,
-- SP 信息 MAX(CASE WHEN tm.member_role = 'SP' THEN tm.person_id END) AS salesmanId
FROM exp_tender t LEFT JOIN exp_tender_member tm ON t.tender_id = tm.tender_id AND tm.status = 'ENABLED'
AND t.tender_code LIKE CONCAT('%', #{req.tenderCode}, '%')
AND t.tender_name LIKE CONCAT('%', #{req.tenderName}, '%')
AND t.tender_type = #{req.tenderType}
AND t.tender_mode = #{req.tenderMode}
AND t.company_id = #{req.purchaserId}
AND t.status = #{req.status}
AND t.project_id = #{req.projectId}
AND t.created_by = #{req.createdBy}
AND t.is_tax_included = #{req.isTaxIncluded}
AND t.purchase_nature = #{req.purchaseNature}
AND t.bid_start_time >= #{req.bidStartTimeStart}
AND t.bid_start_time <= #{req.bidStartTimeEnd}
AND t.bid_end_time >= #{req.bidEndTimeStart}
AND t.bid_end_time <= #{req.bidEndTimeEnd}
GROUP BY t.tender_id
ORDER BY t.created_time DESC

SELECT COUNT(1)
FROM exp_tender
WHERE tender_code = #{tenderCode}

    AND tender_id != #{excludeTenderId}
